SELECT id, store_name, city, sqft, AVG(sqft) OVER (ORDER BY sqft, id ROWS BETWEEN 5 PRECEDING AND 1 PRECEDING) AS sqft_avg_5_prior, LAST_VALUE(region) IGNORE NULLS OVER (PARTITION BY YEAR(opened_date), city ORDER BY opened_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_region, SUM(sqft) OVER (ORDER BY sqft, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_sqft, ROW_NUMBER() OVER (PARTITION BY city ORDER BY opened_date, id) AS row_seq FROM stores
